import{_ as o,o as a,c as u,ag as l}from"./chunks/framework.D5hoimZQ.js";const _=JSON.parse('{"title":"10 小说杂集与玄学","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/notes/10_小说杂集与玄学.md","filePath":"topics/tianya/notes/10_小说杂集与玄学.md"}'),i={name:"topics/tianya/notes/10_小说杂集与玄学.md"};function q(e,t,r,h,n,d){return a(),u("div",null,[...t[0]||(t[0]=[l('<h1 id="_10-小说杂集与玄学" tabindex="-1">10 小说杂集与玄学 <a class="header-anchor" href="#_10-小说杂集与玄学" aria-label="Permalink to &quot;10 小说杂集与玄学&quot;">​</a></h1><p>本卷 23 帖：史论 3、小说 9、玄学 8、经济评论 1、商业 2（同书两版合并）。全部观点摘自原帖。</p><h2 id="一、史论与考据" tabindex="-1">一、史论与考据 <a class="header-anchor" href="#一、史论与考据" aria-label="Permalink to &quot;一、史论与考据&quot;">​</a></h2><h3 id="_111《巍巍大汉-英雄的时代》上医治国1984-2018—2019" tabindex="-1">111《巍巍大汉：英雄的时代》上医治国1984（2018—2019） <a class="header-anchor" href="#_111《巍巍大汉-英雄的时代》上医治国1984-2018—2019" aria-label="Permalink to &quot;111《巍巍大汉：英雄的时代》上医治国1984（2018—2019）&quot;">​</a></h3><ul><li>汉史长篇连载，从刘邦草莽写到宣帝朝霍家覆灭，9000 余楼。</li><li>最大特色是&quot;去神话&quot;讲史：蛟龙附身只是楚地野合的遮羞布，吕公嫁女靠的是相面直觉，开国神话被一一还原为人事。</li><li>对制度与人性的分析扎实：周亚夫平七国之乱&quot;把梁国抛出去消耗叛军&quot;的狠辣计算、汉宣帝对霍光&quot;超规格办丧事&quot;的隐忍，都写得有职场剧质感。</li><li>金句：&quot;如果当时刘太公看到的不是一条蛟龙，而是隔壁村的王二麻子，那事情可能就更接近于真实。&quot;</li></ul><h3 id="_154《沙梨熊全集》沙梨熊-2005-年起" tabindex="-1">154《沙梨熊全集》沙梨熊（2005 年起） <a class="header-anchor" href="#_154《沙梨熊全集》沙梨熊-2005-年起" aria-label="Permalink to &quot;154《沙梨熊全集》沙梨熊（2005 年起）&quot;">​</a></h3><ul><li>煮酒论史八卦合集：&quot;帝国斜阳——末代督抚们的最终结局&quot;&quot;北洋二十四上将&quot;&quot;伪军十大将领&quot;&quot;国军抗战八大新军将领&quot;等系列，专写大变局中人物的收场。</li><li>文风刻毒而见史识：每人小传三五行，末尾一句毒评定调；写华盛顿竟用文言仿《史记》笔法，戏谑中见功力。</li><li>晚期文章以&quot;盘口&quot;（赌局）论政治转型，是全帖最见思想锋芒的部分。</li><li>金句：&quot;极权如同练邪门武功，因为邪所以命门一定有，这克服不了。&quot;</li></ul><h3 id="_190《宝钗比黛玉大八岁》无名寒士-2016—2019" tabindex="-1">190《宝钗比黛玉大八岁》无名寒士（2016—2019） <a class="header-anchor" href="#_190《宝钗比黛玉大八岁》无名寒士-2016—2019" aria-label="Permalink to &quot;190《宝钗比黛玉大八岁》无名寒士（2016—2019）&quot;">​</a></h3><ul><li>红学索隐神帖，核心论点：以原文时间线严格推算，薛宝钗比林黛玉大八岁；贾母&quot;掰谎&quot;、傅秋芳二十三岁未嫁等段落全是作者针对宝钗的暗笔。</li><li>更进一层：《红楼梦》是明清易代血泪史——林为木、喻汉喻明，薛为草、喻夷喻清；全书提及的历史人物止于明，无一清朝人，故写的是明末；作者断为傅山，宝玉即传国玉玺／国权。</li><li>方法论价值在&quot;逐词全书一致&quot;的细读示范，结论争议极大，但文本功夫远超泛泛而谈的红学普及帖。</li><li>金句：&quot;宁说作者数学差，不怪自己水平低。&quot;</li></ul><h2 id="二、小说" tabindex="-1">二、小说 <a class="header-anchor" href="#二、小说" aria-label="Permalink to &quot;二、小说&quot;">​</a></h2><h3 id="_210《烟云》赵明-当代" tabindex="-1">210《烟云》赵明（当代） <a class="header-anchor" href="#_210《烟云》赵明-当代" aria-label="Permalink to &quot;210《烟云》赵明（当代）&quot;">​</a></h3><ul><li>烟草专卖系统行业官场小说：3·15 销毁假烟开场，假烟大案牵出稽查处长高远、外资董事长焦昺章、红二代广告商蔡康、市长戚为群各色人等。</li><li>行业内幕具体可信：邮车夹带、稽查放水、高速交警受贿放行，写得像纪事；焦昺章&quot;油尽灯枯&quot;、情人怀上市长骨肉等私生活写法大胆，政商联姻各怀算盘。</li><li>结尾以扶贫、无人机配送收束成主旋律，前讽后颂，稍显割裂。</li><li>金句：&quot;商界无雷锋，利是永动机。若要得大利，须先与人利。认人最重要，双赢最安全。&quot;</li></ul><h3 id="_112《盛世狂歌》合欢教主-2018" tabindex="-1">112《盛世狂歌》合欢教主（2018） <a class="header-anchor" href="#_112《盛世狂歌》合欢教主-2018" aria-label="Permalink to &quot;112《盛世狂歌》合欢教主（2018）&quot;">​</a></h3><ul><li>明初武侠长篇：洪熙元年，二十年前被九大派剿灭的合欢教少主任逍遥提&quot;多情刃&quot;逐个索命。</li><li>设定有新意：靖难后朝廷册封九派、军户制下&quot;军官近半出自武林&quot;，江湖与庙堂互为表里，故副题称&quot;文字版大明清明上河图&quot;。</li><li>古龙腔的文字模仿扎实，血色马车、夺魂令等意象漂亮；已出版，作者自曝把建昌卫误写成建宁卫，编辑也没查出来。</li><li>金句：&quot;盛世男儿泪，乱世英雄血，狂歌一曲与谁解？江山如画，我心如雪。&quot;</li></ul><h3 id="_193《生在南北朝你就死定了》浮生若梦87-2017" tabindex="-1">193《生在南北朝你就死定了》浮生若梦87（2017） <a class="header-anchor" href="#_193《生在南北朝你就死定了》浮生若梦87-2017" aria-label="Permalink to &quot;193《生在南北朝你就死定了》浮生若梦87（2017）&quot;">​</a></h3><ul><li>以北魏为舞台的历史吐槽小说：冯太后诛乙浑、拓跋弘猜忌慕容白曜等正史骨架，加虚构的慕容傥兄弟与彭城公主感情线。</li><li>网感极强的段子体：&quot;尼古拉斯·太后·冯&quot;&quot;热情礼貌一问三不知&quot;，把正史讲成脱口秀；结构松散未完，但作为南北朝通俗入门读物趣味性一流。</li><li>金句：&quot;高手不是一日练成的，是需要百分之九十九的汗水和百分之一的机会——当然后者比前者重要一万倍。&quot;</li></ul><h3 id="_170《覆帝记》鲜于冶銋-2018—2019" tabindex="-1">170《覆帝记》鲜于冶銋（2018—2019） <a class="header-anchor" href="#_170《覆帝记》鲜于冶銋-2018—2019" aria-label="Permalink to &quot;170《覆帝记》鲜于冶銋（2018—2019）&quot;">​</a></h3><ul><li>清末奇幻长篇：甲午黄海海战开场，漕帮关门弟子李白安等一群少年卷入国运，随后环游世界历险，海外线甚至埋了幼年希姆莱的彩蛋，后期转向推背图与&quot;书山&quot;玄境。</li><li>野心大而枝蔓多、更新缓慢；但&quot;为无名者作传&quot;的立意诚恳，卷首明言&quot;青史里几行名姓，背后垫着千万孤骨荒丘&quot;。</li><li>金句：&quot;城头变幻大王旗，兴亡尽是百姓苦。&quot;</li></ul><h3 id="_148《重世之门》牧清笛-2016—2018" tabindex="-1">148《重世之门》牧清笛（2016—2018） <a class="header-anchor" href="#_148《重世之门》牧清笛-2016—2018" aria-label="Permalink to &quot;148《重世之门》牧清笛（2016—2018）&quot;">​</a></h3><ul><li>玄幻：由种地老农&quot;易大民&quot;代笔讲儿子易凡失踪——起因是村后一座方正得反常的黄土山，取土取出一扇&quot;重世之门&quot;。</li><li>开头是难得的乡土笔法，父辈唠叨里的秦岭农村写得很实；入门后转为上古江湖与洪荒神魔，第一部以易凡觉醒冰寒之体收束。从民间怪谈入口再入玄幻，在同类帖里少见。</li><li>金句：&quot;我们觉得神秘难测，纯粹只是因为不懂。若是有一天明白了其中内情，也许就会觉得不过如此。&quot;</li></ul><h3 id="_204《伏羲密码》十四-001-2016—2018" tabindex="-1">204《伏羲密码》十四 001（2016—2018） <a class="header-anchor" href="#_204《伏羲密码》十四-001-2016—2018" aria-label="Permalink to &quot;204《伏羲密码》十四 001（2016—2018）&quot;">​</a></h3><ul><li>探险悬疑：古生物研究所跑腿员齐天押运化石，飞机在鄱阳湖老爷庙&quot;中国百慕大&quot;被云漩涡吞没。</li><li>主线是&quot;连山卫&quot;对&quot;归藏门&quot;争夺&quot;伏羲基因&quot;，老王叛变、人皮天书、傀儡控制等桥段密度极高，2018 年断更于毒烟昏迷处，未完。俗套但有速度感。</li><li>金句：&quot;这可是个等死的好机会。&quot;</li></ul><h3 id="_113《暗海沉沙》古潼-2018" tabindex="-1">113《暗海沉沙》古潼（2018） <a class="header-anchor" href="#_113《暗海沉沙》古潼-2018" aria-label="Permalink to &quot;113《暗海沉沙》古潼（2018）&quot;">​</a></h3><ul><li>与《伏羲密码》同一位作者（本名贺宝栋，帖内自报家门并列出已出版书目），深海版：前海军蛙人古潼与渔民花小七等四人追寻海底&quot;龙宫&quot;。</li><li>远古建筑群、史前巨蟹、&quot;龙骨背&quot;食人鱼围船等设定完整，节奏比《伏羲密码》更稳；第一部自称完稿连载，结尾停在一张泛黄相片上，仍是钩子。</li><li>金句：&quot;善恶一念，佛魔难分，真相，考验着人性。&quot;</li></ul><h3 id="_186《慧商学院》大秦的疆土-2018" tabindex="-1">186《慧商学院》大秦的疆土（2018） <a class="header-anchor" href="#_186《慧商学院》大秦的疆土-2018" aria-label="Permalink to &quot;186《慧商学院》大秦的疆土（2018）&quot;">​</a></h3><ul><li>教学型小说：借虚构的&quot;慧商学院&quot;把科特勒《营销管理》体系串讲一遍，立论是&quot;新营销没有脱离传统营销体系，只是换了身更潮的装扮&quot;；首创&quot;名、术、融、势、道&quot;五级营销分级说。</li><li>小说性弱、课件性强，但作为免费营销教材确有诚意；主角靠&quot;社会价值&quot;&quot;坚韧&quot;两个回答赢得面试，价值观也摆得端正。</li><li>金句：&quot;理论概括不一定是越全面越好，而应该是越容易实践越好。往哲学里靠，就是知行合一的意思。&quot;</li></ul><h3 id="_157《苦望》晨风文学-2018—2019" tabindex="-1">157《苦望》晨风文学（2018—2019） <a class="header-anchor" href="#_157《苦望》晨风文学-2018—2019" aria-label="Permalink to &quot;157《苦望》晨风文学（2018—2019）&quot;">​</a></h3><ul><li>苦情小说：地震一夜夺去脑瘫男孩苏晨的双亲，姐姐苏锦带着弟弟从山村苦读进大学，靠家教与学长司徒鸿岳支撑。作者自言取材于朋友妻子的&quot;真实故事&quot;，开篇以溪中落叶立意：&quot;即便生命已经逝去，也要把这一抹最后的绿色留在世间。&quot;</li><li>煽情笔法直白甚至笨拙，但底层家庭&quot;一人病、全家贫&quot;的细节是真实的，催泪之外有社会学切片价值。未完。</li></ul><h2 id="三、玄学与杂谈" tabindex="-1">三、玄学与杂谈 <a class="header-anchor" href="#三、玄学与杂谈" aria-label="Permalink to &quot;三、玄学与杂谈&quot;">​</a></h2><h3 id="_29《异人启示录》佩伭-2011—2018" tabindex="-1">29《异人启示录》佩伭（2011—2018） <a class="header-anchor" href="#_29《异人启示录》佩伭-2011—2018" aria-label="Permalink to &quot;29《异人启示录》佩伭（2011—2018）&quot;">​</a></h3><ul><li>天涯最著名的&quot;神棍帖&quot;之一：楼主自称&quot;异人&quot;，讲外星经历、吸食魂魄的邪恶天使、梦境前世与&quot;镜族&quot;约定，八年更新十余万楼。</li><li>魅力不在灵异而在人生劝诫：谈恐惧时说愤怒中&quot;去行动或许会有一线生机&quot;；谈读书主张读与想三七开，&quot;圣人都劝多读书，我来说说少读书&quot;。</li><li>半真半假、欲言又止的文体自成一家，信者极信，疑者当文学读，两头都不亏。</li><li>金句：&quot;若想文字传世，都需牺牲自己。&quot;</li></ul><h3 id="_97《真传一句话-假传万卷书》乾鹿丰-2016" tabindex="-1">97《真传一句话，假传万卷书》乾鹿丰（2016） <a class="header-anchor" href="#_97《真传一句话-假传万卷书》乾鹿丰-2016" aria-label="Permalink to &quot;97《真传一句话，假传万卷书》乾鹿丰（2016）&quot;">​</a></h3><ul><li>中医出身楼主讲预测术总源：四门（易经、奇门、太乙、大六壬）皆根于日月五星运行；十二生肖源于木星 11.86 年公转；岁差解释先天八卦到后天八卦的演进——框架自洽，天文底子是真的。</li><li>缺点同样明显：以 2016 年 9 月股灾自证神算、&quot;免费算卦损运气&quot;等说法无法验证，狂言多于论证；但&quot;真传就是讲出来人人能听懂&quot;的态度，在故弄玄虚的圈子里算清流。</li><li>金句：&quot;你讲出的东西别人听不懂，只能证明你根本就不懂。&quot;</li></ul><h3 id="_28《山医卜命相五术杂谈》-33《用我30年的经历揭开周易的神秘》四书五经丶-2015—2017" tabindex="-1">28《山医卜命相五术杂谈》／33《用我30年的经历揭开周易的神秘》四书五经丶（2015—2017） <a class="header-anchor" href="#_28《山医卜命相五术杂谈》-33《用我30年的经历揭开周易的神秘》四书五经丶-2015—2017" aria-label="Permalink to &quot;28《山医卜命相五术杂谈》／33《用我30年的经历揭开周易的神秘》四书五经丶（2015—2017）&quot;">​</a></h3><ul><li>同一作者邓建忠的两版帖：55 岁广东建材商人，命理近三十年；33 帖自述把首发于杂谈的旧帖&quot;修订补充、脱水整合&quot;重发，两帖案例大量重合。</li><li>特色是全用实战卦例说话：女儿失踪得蹇之比卦断方位、&quot;八不测&quot;中&quot;嬉戏嘈杂不测&quot;的职业操守、桐柏水灾死者八字与面相互证的推理。</li><li>技法未必可证，但&quot;心易法门——卦从心生&quot;把预测讲成直觉训练，楼主坚持免费并公开防冒牌声明，人品成色高于多数同行。</li><li>金句：&quot;心诚则灵&quot;的前提，是&quot;不诚不测&quot;。</li></ul><h3 id="_30-31《写在脸上的风水》一二卷-禅海商道-2016—2017" tabindex="-1">30/31《写在脸上的风水》一二卷 禅海商道（2016—2017） <a class="header-anchor" href="#_30-31《写在脸上的风水》一二卷-禅海商道-2016—2017" aria-label="Permalink to &quot;30/31《写在脸上的风水》一二卷 禅海商道（2016—2017）&quot;">​</a></h3><ul><li>面相课程帖：小学（三停六府）、中学（四渎五岳十二宫）、大学（&quot;流年为风、定位为水&quot;的面相风水）、研究生（《冰鉴》逐段讲解），体系完整可当讲义。</li><li>卷二更杂：《冰鉴》声音篇讲得极细（&quot;喜如折竹，怒如阴雷起地，哀如击薄冰，乐如雪舞风前&quot;），又夹带《黄帝内经》与&quot;抱大腿&quot;生意经。</li><li>难得在立意：&quot;相随心转&quot;&quot;多笑&quot;&quot;改变自己命运的唯一办法就是帮助别人&quot;；赏金六万印书三千册，是天涯少见的知识变现样本。</li><li>金句：&quot;名为教人看相，实为授人心法。&quot;</li></ul><h3 id="_187《请块-开光-玉-不如养活的灵宠》神奇的老贼头-2010—2014" tabindex="-1">187《请块&quot;开光&quot;玉，不如养活的灵宠》神奇的老贼头（2010—2014） <a class="header-anchor" href="#_187《请块-开光-玉-不如养活的灵宠》神奇的老贼头-2010—2014" aria-label="Permalink to &quot;187《请块&quot;开光&quot;玉，不如养活的灵宠》神奇的老贼头（2010—2014）&quot;">​</a></h3><ul><li>以&quot;业内人拆台&quot;姿态讲民俗：真开光要高道行自毁根基，市面开光玉基本是骗局；随后系统介绍龟（玄武镇宅）、雄鸡（朱雀克阴）、猫（司地府）、鲤鱼（替身挡劫、养十年日念道德经）的养法。</li><li>半是民俗志半是段子，&quot;土里千年，不敌好鸡一只&quot;这类口诀编得有鼻子有眼；立场清醒，反复强调灵宠只是辅助，运气主要靠自己去挣。</li><li>金句：&quot;真正高级的黑社会，决对比你见过最绅士的人还要绅士，但手段却比你见过最流氓的人还要流氓。&quot;</li></ul><h3 id="_192《戏说三界之事》脚踏阴阳" tabindex="-1">192《戏说三界之事》脚踏阴阳 <a class="header-anchor" href="#_192《戏说三界之事》脚踏阴阳" aria-label="Permalink to &quot;192《戏说三界之事》脚踏阴阳&quot;">​</a></h3><ul><li>七言打油诗集：修真、三界封印、外族布阵、阴兵入华，阴谋论大杂烩，后半段与前半内容重复。</li><li>楼主自己标着&quot;本故事纯属虚构，如有雷同不知咋说&quot;，自知之明齐全；作为玄学帖成色最低，当顺口溜读尚可。</li></ul><h3 id="_162《雨夜谈经》巴山夜雨2016abc-2019" tabindex="-1">162《雨夜谈经》巴山夜雨2016abc（2019） <a class="header-anchor" href="#_162《雨夜谈经》巴山夜雨2016abc-2019" aria-label="Permalink to &quot;162《雨夜谈经》巴山夜雨2016abc（2019）&quot;">​</a></h3><ul><li>名为&quot;谈经&quot;实为谈经济：每日点评宏观时事，核心主张&quot;拯救制造业是目前经济工作的主线&quot;，路径是降收入、降成本，反复拆解&quot;反通胀死循环&quot;。</li><li>对 LPR、房地产税、地摊经济的判断逻辑链清晰，&quot;房地产税一定会推出，但一定不会很快&quot;克制而准确；实为这批杂集里最&quot;干货&quot;的时评连载之一。</li><li>金句：&quot;政策决定短期，规律决定长期。&quot;</li></ul><h2 id="四、商业-同书两版合并" tabindex="-1">四、商业（同书两版合并） <a class="header-anchor" href="#四、商业-同书两版合并" aria-label="Permalink to &quot;四、商业（同书两版合并）&quot;">​</a></h2><h3 id="_71《商业筹码狙击战-独家首发-》-96【已出版】xiaozhu909-2013" tabindex="-1">71《商业筹码狙击战（独家首发）》／96【已出版】xiaozhu909（2013） <a class="header-anchor" href="#_71《商业筹码狙击战-独家首发-》-96【已出版】xiaozhu909-2013" aria-label="Permalink to &quot;71《商业筹码狙击战（独家首发）》／96【已出版】xiaozhu909（2013）&quot;">​</a></h3><ul><li>两个 PDF 为同一连载：71 为天涯首发整理版，96 为标注&quot;已出版&quot;并混入读者楼层互动的版本，正文一致，合并为一节。</li><li>内容是 2013 年前后的商战案例复盘：雷士照明 45:55 股权埋雷、蒙牛与摩根的资本蜜月、王老吉商标&quot;二母夺子&quot;、iPad 商标、京东自建物流、吉利&quot;蛇吞象&quot;等，八章一套&quot;后危机时代生存学&quot;。</li><li>价值在态度：为&quot;奸商&quot;作辩护词——法律有漏洞、市场不公平，出阴招首先是求生；楼中讨论更直白，点破&quot;官为体、商为用&quot;的畸形生态。</li><li>金句：&quot;如果说西方社会是商业社会，那么我们就是官体商用的社会……想要有钱必须借助权力通行，而想要升官又必须依靠钱来开路。&quot;</li></ul><h2 id="五、总览与心得" tabindex="-1">五、总览与心得 <a class="header-anchor" href="#五、总览与心得" aria-label="Permalink to &quot;五、总览与心得&quot;">​</a></h2><p>这批&quot;杂集&quot;里，最被低估的是三样。</p><p>其一是《雨夜谈经》（162）。它被顺手归进玄学卷，实则是一份逐日更新的宏观时评：用&quot;降收入、降成本&quot;一个框架贯通房价、汇率、地摊与 LPR，克制、讲逻辑、极少情绪词，比同期绝大多数财经帖更接近专业分析。它在天涯既不灵异也不猎奇，几乎没有存在感——但多年后回看，&quot;政策决定短期，规律决定长期&quot;这十个字，比任何预言都耐放。</p><p>其二是《写在脸上的风水》（30/31）。&quot;面相&quot;两个字劝退了九成理性读者，可这套帖实际是借相术外壳教人观察、分类与自我修整：三停六府是给脸建坐标系，《冰鉴》是给声音建坐标系，落脚点永远是&quot;相随心转、助人改运&quot;。它可能是天涯所有玄学帖里唯一把&quot;改命&quot;解释为&quot;改行为&quot;的，知识密度和完成度都配得上三百万阅读。</p><p>其三是《慧商学院》（186）。它不像小说，甚至不像帖子，像一部免费公开课：把科特勒体系拆成剧情、作业和五级&quot;名术融势道&quot;，认真到笨拙。它没有爽点，传播注定失败，但对想系统学营销的人，比十本网红商业书都实惠。</p><p>至于最名副其实的神贴，仍是《宝钗比黛玉大八岁》（190）：无论是否接受&quot;傅山著书、宝钗喻清&quot;的结论，它示范了&quot;一个词全书一致&quot;的文本细读，把红学从赏析拉回证据——这份方法论本身，就值回全部争论。</p>',52)])])}const c=o(i,[["render",q]]);export{_ as __pageData,c as default};
